// _policy_putSliceGroup writes the encoding of x, a []Group, into the end of
// buf, which has room for it, and returns its length. It fails for a value that
// fails to encode, which loc and num locate.
func _policy_putSliceGroup(buf []byte, x []Group, loc string, num int) (int, error) {
	i := len(buf)
	for k := len(x) - 1; k >= 0; k-- {
		w, err := x[k].encodeKanon(buf[:i])
		if err != nil {
			return 0, err
		}
		i -= w
		i = wire.PutUvarint(buf, i, uint64(w))
	}
	i = wire.PutUvarint(buf, i, uint64(len(buf)-i))
	return len(buf) - i, nil
}

