// _policy_tagPolicy returns the error of the canonical decode of Policy for the
// tag at data[i], which begins no field after the fields that the decode read
// before it. data starts at offset off of the slab.
func _policy_tagPolicy(data []byte, i int, prior uint64, off int) error {
	tag, n := wire.Uvarint(data[i:])
	if n <= 0 {
		return wire.ReadError(n, "Policy", 0, off+i)
	}
	if n > 1 && data[i+n-1] == 0 {
		return wire.LongFormError(n, "Policy", 0, off+i)
	}
	if tag>>3 == 0 {
		return wire.TagError(tag, "Policy", 0, off+i)
	}
	if tag>>3 <= prior {
		return wire.OrderError(tag>>3, prior, "Policy", 0, off+i)
	}
	switch tag >> 3 {
	case 1:
		return wire.FormatError(tag, wire.Bytes, "Policy.Quorum", off+i)
	case 2:
		return wire.FormatError(tag, wire.Bytes, "Policy.Logs", off+i)
	case 3:
		return wire.FormatError(tag, wire.Bytes, "Policy.Witnesses", off+i)
	case 4:
		return wire.FormatError(tag, wire.Bytes, "Policy.Groups", off+i)
	}
	return wire.UnknownFieldError(tag>>3, "Policy", 0, off+i)
}

// _policy_resetSliceLog empties the []Log that x points at and resets every
// element of its capacity, which keeps its memory for the next decode.
func _policy_resetSliceLog(x *[]Log) {
	s := (*x)[:cap(*x)]
	for k := range s {
		s[k].Reset()
	}
	*x = (*x)[:0]
}

